{"code": "def authorize(request: dict, policies: list[dict]) -> str:
    """
    Decide access requests against a policy set using deny-overrides logic.

    Returns "ALLOW" or "DENY".
    """
    _validate_request(request)
    _validate_policies(policies)

    subject = request["subject"]
    roles = request["roles"]
    action = request["action"]
    resource = request["resource"]

    # Check for matching DENY (deny-overrides)
    for policy in policies:
        if (policy["effect"] == "DENY" and
            _policy_matches(policy, subject, roles, action, resource)):
            return "DENY"

    # Check for matching ALLOW
    for policy in policies:
        if (policy["effect"] == "ALLOW" and
            _policy_matches(policy, subject, roles, action, resource)):
            return "ALLOW"

    # Default deny
    return "DENY"


def _validate_request(request):
    """Validate request has all required fields."""
    required_fields = ["subject", "roles", "action", "resource"]
    for field in required_fields:
        if field not in request:
            raise ValueError(f"Request missing required field: {field}")

    if not isinstance(request["roles"], list):
        raise ValueError(f"Request 'roles' must be a list, got {type(request['roles']).__name__}")


def _validate_policies(policies):
    """Validate all policies have required fields and valid effects."""
    for policy in policies:
        required_fields = ["effect", "principal", "action", "resource"]
        for field in required_fields:
            if field not in policy:
                raise ValueError(f"Policy missing required field: {field}")

        effect = policy["effect"]
        if effect not in ("ALLOW", "DENY"):
            raise ValueError(f"Policy has invalid effect: {effect}")


def _policy_matches(policy, subject, roles, action, resource):
    """Check if a policy matches the request."""
    return (_matches_principal(policy["principal"], subject, roles) and
            _matches_action(policy["action"], action) and
            _matches_resource(policy["resource"], resource))


def _matches_principal(principal, subject, roles):
    """Check if principal matches the request subject and roles."""
    if principal == "*":
        return True

    if principal.startswith("user:"):
        return principal[5:] == subject

    if principal.startswith("role:"):
        role = principal[5:]
        return role in roles

    return False


def _matches_action(pattern, action):
    """Check if action matches the pattern."""
    if pattern == "*":
        return True

    if pattern.endswith("*"):
        prefix = pattern[:-1]
        return action.startswith(prefix)

    return pattern == action


def _matches_resource(pattern, resource):
    """Check if resource matches the pattern."""
    if pattern == "*":
        return True

    if pattern.endswith("*"):
        prefix = pattern[:-1]
        return resource.startswith(prefix)

    return pattern == resource"}
